# hermes-device-sync: plugs into the shared `hermes` launcher. Before Hermes opens: sync, ask about
# skill updates (if Hermes Skills Updater is installed), one Hermes at a time, bring in a newer
# conversation from another device. After it closes: sync. `Sync-Hermes` = sync now.
# Generated by setup.py; re-run setup to change.
$HermesSyncScripts = '__SCRIPTS__'
$HermesSyncPython = '__PYTHON__'
function Sync-Hermes { & $HermesSyncPython (Join-Path $HermesSyncScripts 'sync.py') }
if (-not $global:HermesHooks) { $global:HermesHooks = @{} }
$global:HermesHooks['before-20-sync'] = {
    Sync-Hermes
    $u = Join-Path $(if ($env:HERMES_HOME) { $env:HERMES_HOME } else { Join-Path $env:LOCALAPPDATA 'hermes' }) 'scripts\hermes-skills-updater.py'
    if (Test-Path $u) { & $HermesSyncPython $u prompt }
    # One Hermes at a time: if another device has Hermes open, ask (close it there / stop here).
    $env:HERMES_SYNC_WRAPPER_PID = $PID
    & $HermesSyncPython (Join-Path $HermesSyncScripts 'presence.py') start
    if ($LASTEXITCODE -eq 3) { Write-Host 'OK - keep using Hermes on the other device.'; $global:HermesStop = $true; return }
    # a newer conversation on another device is imported (Hermes's Terminal, if installed, then opens it)
    & $HermesSyncPython (Join-Path $HermesSyncScripts 'handoff.py') pick 2>$null | Out-Null
}
$global:HermesHooks['after-80-sync'] = {
    Write-Host 'Syncing...' -ForegroundColor DarkGray
    & $HermesSyncPython (Join-Path $HermesSyncScripts 'presence.py') stop 2>$null
    Sync-Hermes
}
